import time
import threading
def task_func(delay_time: float = 1.0, num_threads: int = 5):
    if isinstance(num_threads, bool) or not isinstance(num_threads, int):
        raise TypeError("num_threads must be a non-negative integer")
    if num_threads < 0:
        raise ValueError("num_threads must be non-negative")

    try:
        delay = float(delay_time)
    except (TypeError, ValueError):
        raise TypeError("delay_time must be a non-negative number")

    if delay < 0 or delay != delay or delay == float("inf"):
        raise ValueError("delay_time must be a finite non-negative number")

    results = [None] * num_threads

    def worker(index):
        time.sleep(delay)
        results[index] = f"Delay in thread {index} completed"

    threads = []
    for i in range(num_threads):
        thread = threading.Thread(target=worker, args=(i,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return results
